@Injectable()
export class ResourceTypeConvertService {
  private resourceTypeConvert: ResourceTypeConvert;

  public constructor(
    private readonly formattingUtils: FormattingUtilsService,
    private readonly customLogger: AppLogger,
  ) {}

  public async convert(
    data: ResourceTypeResourceDto,
  ): Promise<ResourceTypeConvert> {
    const context: JobsLogContext = {
      method: 'convert',
      service: 'ResourceTypeConvertService',
    };
    if (!data) {
      throw new HttpException(
        `payload '${data}'  are empty.`,
        HttpStatus.BAD_REQUEST,
      );
    }
    try {
      const {
        HANDLE,
        RESOURCE_TYPE_BO: recourceTypeBo,
        RESOURCE_BO: resourceBo,
        ...commonFields
      } = data;
      const plant = Number(
        this.formattingUtils.extractSubstringBetweenColonAndComma(
          String(resourceBo),
        ),
      );
      const resourceId = this.formattingUtils.extractSubstringAfterLastColon(
        String(resourceBo),
      );
      const resourceType = this.formattingUtils.extractSubstringAfterLastColon(
        String(recourceTypeBo),
      );
      const payload = {
        plant,
        resourceId,
        resourceType,
        ...commonFields,
      };
      this.resourceTypeConvert = payload;
      return this.resourceTypeConvert;
    } catch (error) {
      this.customLogger.error(
        `error in converting resource type convert${error}`,
        context,
      );
      throw new HttpException(
        `error in converting resource type convert `,
        HttpStatus.BAD_REQUEST,
      );
    }
  }
}

import { HttpException, HttpStatus } from '@nestjs/common';
import { MappedOutput } from '@/common/mapping/interface/mapping.model';

export class FormattingUtilsService {
  public substring(
    payload: MappedOutput,
    ...columns: Array<string>
  ): MappedOutput {
    if (payload && columns) {
      const reformattedPayload = { ...payload };
      for (const column of columns) {
        if (reformattedPayload[column]) {
          const splittedValue = String(reformattedPayload[column]).split(',');
          if (splittedValue.length >= 2) {
            reformattedPayload[column] = splittedValue[1].trim();
          }
        }
      }
      return reformattedPayload;
    }
    throw new HttpException(
      `payload '${JSON.stringify(payload)}' or columns '${columns}' are empty.`,
      HttpStatus.BAD_REQUEST,
    );
  }

  public extractSubstringBetweenColonAndComma(inputString: string): string {
    if (inputString) {
      const lastColonIndex = inputString.lastIndexOf(':');
      const commaIndex = inputString.lastIndexOf(',');

      if (
        lastColonIndex !== -1 &&
        commaIndex !== -1 &&
        lastColonIndex < commaIndex
      ) {
        return inputString.slice(lastColonIndex + 1, commaIndex);
      }
      return ''; // Or handle the case when either the colon or the comma is not found
    }
    throw new HttpException(
      `input'${inputString}' is  empty.`,
      HttpStatus.BAD_REQUEST,
    );
  }

  public extractSubstringAfterLastColon(inputString: string): string {
    if (inputString) {
      const lastColonIndex = inputString.lastIndexOf(',');
      if (lastColonIndex !== -1 && lastColonIndex < inputString.length - 1) {
        return inputString.slice(Math.max(0, lastColonIndex + 1));
      }
      return ''; // Or handle the case when there is no substring after the last colon
    }
    throw new HttpException(
      `input'${inputString}' is  empty.`,
      HttpStatus.BAD_REQUEST,
    );
  }
}

