import { RedisConnectionService, JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import {
  createLock,
  NodeRedisAdapter,
  Lock,
  LockAcquisitionError,
  LockHandle,
} from 'redlock-universal';
import { AppLogger } from '@/common/logger/app-logger';
import { asyncSleep } from '@/common/sleep/sleep';

@Injectable()
export class RedisLockService {
  private adapter: NodeRedisAdapter;

  private readonly ttl = 10_000;

  private readonly retryCount = 3;

  private readonly retryDelayMs = 1000;

  // Map to store acquired locks
  private readonly lockMap = new Map<
    string,
    { lock: Lock; handle: LockHandle }
  >();

  public constructor(
    private readonly redisConnection: RedisConnectionService,
    private readonly logger: AppLogger,
  ) {}

  public async onModuleInit(): Promise<void> {
    const client = await this.redisConnection.getClient(); // If async
    this.adapter = new NodeRedisAdapter(client);
  }

  /**
   * Try to acquire a lock with retries (recursive, no while)
   * @param key Lock key
   * @param context JobsLogContext
   * @param attempt Current attempt number (internal)
   * @returns true if acquired, false otherwise
   */
  public async tryLockKey(
    key: string,
    context: JobsLogContext,
    attempt = 1,
  ): Promise<boolean> {
    try {
      const lock: Lock = createLock({
        adapter: this.adapter,
        key,
        ttl: this.ttl,
      });
      const handle: LockHandle = await lock.acquire();

      this.lockMap.set(key, { lock, handle });
      this.logger.debug(
        `Lock acquired for key ${key} (Attempt ${attempt})`,
        context,
      );
      return true;
    } catch (error) {
      const lastError =
        error instanceof Error ? error : new Error(String(error));

      if (error instanceof LockAcquisitionError) {
        this.logger.warn(
          `Timeout acquiring lock for key ${key} (Attempt ${attempt} of ${this.retryCount})`,
          context,
        );
      } else {
        this.logger.error(
          `Error acquiring lock for key ${key} (Attempt ${attempt} of ${this.retryCount}): ${lastError.message}`,
          context,
          lastError,
        );
      }

      if (attempt < this.retryCount) {
        await asyncSleep(this.retryDelayMs);
        return this.tryLockKey(key, context, attempt + 1);
      }

      this.logger.error(
        `Failed to acquire lock for key ${key} after ${this.retryCount} attempts: ${lastError.message}`,
        context,
        lastError,
      );
      return false;
    }
  }

  /**
   * Release a lock using only the key
   * @param key Lock key
   * @param context JobsLogContext
   */
  public async releaseLock(
    key: string,
    context: JobsLogContext,
  ): Promise<void> {
    const lockData = this.lockMap.get(key);
    if (!lockData) {
      this.logger.warn(`No lock found for key ${key} to release`, context);
      return;
    }

    try {
      await lockData.lock.release(lockData.handle);
      this.logger.debug(`Lock released successfully for key ${key}`, context);
      this.lockMap.delete(key);
    } catch (error) {
      this.logger.error(
        `Failed to release lock for key ${key}: ${error.message}`,
        context,
        error,
      );
    }
  }

  /**
   * Lock a key and execute a callback (auto-release)
   * @param key Lock key
   * @param callback Async function to execute while holding the lock
   * @param context JobsLogContext
   * @returns The result of the callback or undefined if failed
   */
  public async lockKeyWithCallback<T>(
    key: string,
    callback: () => Promise<T>,
    context: JobsLogContext,
  ): Promise<T | undefined> {
    const lock: Lock = createLock({
      adapter: this.adapter,
      key,
      ttl: this.ttl,
    });

    try {
      return await lock.using(async (signal) => {
        const result = await callback();
        if (signal.aborted) {
          throw new Error(`Lock lost for key ${key}: ${signal.error?.message}`);
        }
        return result;
      });
    } catch (error) {
      this.logger.error(
        `Error executing callback with lock on key ${key}: ${error.message}`,
        context,
        error,
      );
      return undefined;
    }
  }
}

/**
 * Sleep function
 * @param time number of ms to wait
 * @returns void
 */
export async function asyncSleep(time: number): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, time);
  });
}

