@Injectable()
export class DaprConfigService implements OnModuleInit {
  public constructor(
    private readonly configService: ConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public get bindingPlant(): string {
    return this.configService.get<string>('bindingPlant') ?? '';
  }

  public get bindingUAP(): string {
    return this.configService.get<string>('bindingUAP') ?? '';
  }

  public get bindingProdline(): string {
    return this.configService.get<string>('bindingProdline') ?? '';
  }

  public get bindingWorkCenterList(): string {
    return this.configService.get<string>('bindingWorkCenterList') ?? '';
  }

  public get bindingWorkCenter(): string {
    return this.configService.get<string>('bindingWorkCenter') ?? '';
  }

  public get bindingResource(): string {
    return this.configService.get<string>('bindingResource') ?? '';
  }

  public get bindingResourceTypeResource(): string {
    return this.configService.get<string>('bindingResourceTypeResource') ?? '';
  }

  public onModuleInit(): void {
    this.validateConfiguration();
  }

  private validateConfiguration(): void {
    const context: JobsLogContext = {
      method: 'validateConfiguration',
      service: 'DaprConfigService',
    };
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'bindingPlant', value: this.bindingPlant },
      { key: 'bindingUAP', value: this.bindingUAP },
      { key: 'bindingProdline', value: this.bindingProdline },
      { key: 'bindingWorkCenterList', value: this.bindingWorkCenterList },
      { key: 'bindingWorkCenter', value: this.bindingWorkCenter },
      { key: 'bindingResource', value: this.bindingResource },
      {
        key: 'bindingResourceTypeResource',
        value: this.bindingResourceTypeResource,
      },
    ];

    const missingConfigs = requiredConfigs.filter(
      (config) => config.value === undefined,
    );

    if (missingConfigs.length > 0) {
      for (const config of missingConfigs) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          context,
        );
      }
      throw new Error(
        'Configuration error: Some required configurations are not set.',
      );
    }
  }
}

